//! Basic geometric types shared by the whole crate (`clipper2/clipper.core.h`).

use std::fmt;

/// An integer point, equivalent to `Clipper2Lib::Point64`.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Default)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    #[inline]
    pub const fn new(x: i64, y: i64) -> Self {
        Point64 { x, y }
    }

    /// Rounds a floating point coordinate pair the way Clipper2 does when it
    /// converts an intersection point back into the integer domain
    /// (round half away from zero).
    #[inline]
    pub fn from_f64(x: f64, y: f64) -> Self {
        Point64 {
            x: x.round() as i64,
            y: y.round() as i64,
        }
    }
}

impl fmt::Debug for Point64 {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{},{}", self.x, self.y)
    }
}

/// A single closed polygon.
pub type Path64 = Vec<Point64>;
/// A set of closed polygons.
pub type Paths64 = Vec<Path64>;

/// How the interior of a polygon set is determined, `Clipper2Lib::FillRule`.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FillRule {
    EvenOdd,
    NonZero,
    Positive,
    Negative,
}

/// The boolean operation to perform, `Clipper2Lib::ClipType`.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ClipType {
    None,
    Intersection,
    Union,
    Difference,
    Xor,
}

/// Signed area of a closed path. Positive for counter-clockwise paths when the
/// y axis points up, matching Clipper2's `Area()`.
pub fn area(path: &[Point64]) -> f64 {
    if path.len() < 3 {
        return 0.0;
    }
    // Accumulate exactly in i128, then halve once, so no precision is lost for
    // coordinates in the range Clipper2 supports.
    let mut acc: i128 = 0;
    let mut prev = path[path.len() - 1];
    for &p in path {
        acc += (prev.x as i128 + p.x as i128) * (prev.y as i128 - p.y as i128);
        prev = p;
    }
    -(acc as f64) * 0.5
}

/// `true` when the path's orientation is positive (see [`area`]).
pub fn is_positive(path: &[Point64]) -> bool {
    area(path) > 0.0
}

/// Cross product of `oa` x `ob`, evaluated exactly.
#[inline]
pub fn cross_product(o: Point64, a: Point64, b: Point64) -> i128 {
    (a.x as i128 - o.x as i128) * (b.y as i128 - o.y as i128)
        - (a.y as i128 - o.y as i128) * (b.x as i128 - o.x as i128)
}

/// Dot product of `oa` . `ob`, evaluated exactly.
#[inline]
pub fn dot_product(o: Point64, a: Point64, b: Point64) -> i128 {
    (a.x as i128 - o.x as i128) * (b.x as i128 - o.x as i128)
        + (a.y as i128 - o.y as i128) * (b.y as i128 - o.y as i128)
}

