//! The clipping engine (`clipper2/clipper.engine.h`).
//!
//! Clipper2 implements a Vatti-style sweep. Re-creating that machinery is not
//! necessary to reproduce its *results*, so this port takes the equivalent
//! planar-subdivision route, which is easier to verify:
//!
//! 1. Every input edge is split at each intersection with every other edge and
//!    at every vertex that lies in its interior, producing an arrangement whose
//!    segments only ever meet at shared end points.
//! 2. Duplicate (shared) segments are collapsed, then each remaining segment is
//!    classified by asking whether the result region is filled immediately to
//!    its left and to its right. A segment survives only if the two answers
//!    differ, i.e. it really is part of the boundary of the result, and it is
//!    oriented so the filled side is on its left.
//! 3. The surviving directed segments are stitched back into closed loops.
//!    Loops are then tidied the way Clipper2 tidies its solutions: repeated and
//!    collinear vertices are dropped and degenerate loops are discarded.
//!
//! As in Clipper2, intersection points are rounded back onto the integer grid.

use super::core::*;
use std::collections::HashMap;

/// A directed segment of the arrangement.
#[derive(Clone, Copy)]
struct Seg {
    a: Point64,
    b: Point64,
}

/// Distance used to probe either side of a segment when classifying it. The
/// inputs live on the integer grid, so anything well below one unit lands in
/// the face that the segment borders.
const PROBE: f64 = 1e-6;

/// Largest gap (in grid units) that loop stitching will bridge when rounding
/// has left a T-junction very slightly disconnected.
const STITCH_TOLERANCE_SQ: i128 = 4;

/// Performs `ct` on `subjects` / `clips` using `fill_rule`.
pub fn boolean_op(
    ct: ClipType,
    subjects: &Paths64,
    clips: &Paths64,
    fill_rule: FillRule,
) -> Paths64 {
    if ct == ClipType::None {
        return Paths64::new();
    }

    let subj = prepare(subjects);
    let clp = prepare(clips);

    // Operations that need both operands are empty when the subject is.
    if subj.is_empty() {
        match ct {
            ClipType::Intersection | ClipType::Difference => return Paths64::new(),
            _ => {}
        }
    }
    if clp.is_empty() && ct == ClipType::Intersection {
        return Paths64::new();
    }

    let edges = collect_edges(&subj, &clp);
    if edges.is_empty() {
        return Paths64::new();
    }

    let segments = build_arrangement(&edges);
    let boundary = select_boundary(&segments, &subj, &clp, ct, fill_rule);
    let loops = stitch(&boundary);

    let mut solution = Paths64::new();
    for l in loops {
        if let Some(path) = tidy(l) {
            solution.push(path);
        }
    }
    solution
}

/// Drops repeated vertices (including a closing duplicate) and paths that
/// cannot enclose any area.
fn prepare(paths: &Paths64) -> Paths64 {
    let mut out = Paths64::new();
    for path in paths {
        let mut p: Path64 = Vec::with_capacity(path.len());
        for &pt in path {
            if p.last() != Some(&pt) {
                p.push(pt);
            }
        }
        while p.len() > 1 && p[0] == p[p.len() - 1] {
            p.pop();
        }
        if p.len() >= 3 {
            out.push(p);
        }
    }
    out
}

/// All polygon edges, subject edges first.
fn collect_edges(subj: &Paths64, clp: &Paths64) -> Vec<Seg> {
    let mut edges = Vec::new();
    for paths in [subj, clp] {
        for path in paths {
            for i in 0..path.len() {
                let a = path[i];
                let b = path[(i + 1) % path.len()];
                if a != b {
                    edges.push(Seg { a, b });
                }
            }
        }
    }
    edges
}

/// Splits every edge so that segments meet only at shared end points, then
/// removes duplicates (a segment shared by both operands is kept once).
fn build_arrangement(edges: &[Seg]) -> Vec<Seg> {
    let n = edges.len();
    let mut splits: Vec<Vec<Point64>> = vec![Vec::new(); n];

    // Every vertex is a potential split point for any edge passing through it,
    // and so is every pairwise intersection.
    let mut nodes: Vec<Point64> = Vec::with_capacity(n * 2);
    for e in edges {
        nodes.push(e.a);
        nodes.push(e.b);
    }
    for i in 0..n {
        for j in (i + 1)..n {
            if let Some(p) = intersection_point(&edges[i], &edges[j]) {
                splits[i].push(p);
                splits[j].push(p);
                nodes.push(p);
            }
        }
    }
    nodes.sort_by_key(|p| (p.x, p.y));
    nodes.dedup();

    for (i, e) in edges.iter().enumerate() {
        for &p in &nodes {
            if strictly_inside_edge(e, p) {
                splits[i].push(p);
            }
        }
    }

    let mut segments: Vec<Seg> = Vec::new();
    let mut seen: HashMap<(Point64, Point64), ()> = HashMap::new();
    for (i, e) in edges.iter().enumerate() {
        let cuts = &mut splits[i];
        cuts.retain(|&p| strictly_inside_edge(e, p));
        cuts.sort_by(|&p, &q| {
            dist_sq(e.a, p)
                .cmp(&dist_sq(e.a, q))
                .then((p.x, p.y).cmp(&(q.x, q.y)))
        });
        cuts.dedup();

        let mut from = e.a;
        for &p in cuts.iter() {
            push_unique(&mut segments, &mut seen, from, p);
            from = p;
        }
        push_unique(&mut segments, &mut seen, from, e.b);
    }
    segments
}

fn push_unique(
    segments: &mut Vec<Seg>,
    seen: &mut HashMap<(Point64, Point64), ()>,
    a: Point64,
    b: Point64,
) {
    if a == b {
        return;
    }
    // Key on the unordered end points so that coincident edges from the two
    // operands (or from a self-overlapping operand) collapse into one.
    let key = if (a.x, a.y) <= (b.x, b.y) {
        (a, b)
    } else {
        (b, a)
    };
    if seen.insert(key, ()).is_none() {
        segments.push(Seg { a, b });
    }
}

/// Intersection of two edges, rounded to the integer grid. `None` when they are
/// parallel or do not meet; touching at an end point is reported, because that
/// point still has to become a node of the arrangement.
fn intersection_point(e1: &Seg, e2: &Seg) -> Option<Point64> {
    let d1x = e1.b.x as i128 - e1.a.x as i128;
    let d1y = e1.b.y as i128 - e1.a.y as i128;
    let d2x = e2.b.x as i128 - e2.a.x as i128;
    let d2y = e2.b.y as i128 - e2.a.y as i128;

    let denom = d1x * d2y - d1y * d2x;
    if denom == 0 {
        return None; // parallel or collinear: handled by vertex splitting
    }
    let ox = e2.a.x as i128 - e1.a.x as i128;
    let oy = e2.a.y as i128 - e1.a.y as i128;
    let t_num = ox * d2y - oy * d2x;
    let u_num = ox * d1y - oy * d1x;

    // Require 0 <= t <= 1 and 0 <= u <= 1 without dividing.
    let (lo, hi) = if denom > 0 { (0, denom) } else { (denom, 0) };
    if t_num < lo || t_num > hi || u_num < lo || u_num > hi {
        return None;
    }
    let t = t_num as f64 / denom as f64;
    Some(Point64::from_f64(
        e1.a.x as f64 + t * d1x as f64,
        e1.a.y as f64 + t * d1y as f64,
    ))
}

/// `true` when `p` lies on `e` strictly between its end points.
fn strictly_inside_edge(e: &Seg, p: Point64) -> bool {
    if p == e.a || p == e.b {
        return false;
    }
    cross_product(e.a, e.b, p) == 0
        && dot_product(e.a, p, e.b) > 0
        && dot_product(e.b, p, e.a) > 0
}

#[inline]
fn dist_sq(a: Point64, b: Point64) -> i128 {
    let dx = b.x as i128 - a.x as i128;
    let dy = b.y as i128 - a.y as i128;
    dx * dx + dy * dy
}

/// Keeps the segments that bound the result, oriented with the filled side on
/// the left (so outer loops come out positively oriented).
fn select_boundary(
    segments: &[Seg],
    subj: &Paths64,
    clp: &Paths64,
    ct: ClipType,
    fill_rule: FillRule,
) -> Vec<Seg> {
    let mut out = Vec::new();
    for s in segments {
        let dx = (s.b.x - s.a.x) as f64;
        let dy = (s.b.y - s.a.y) as f64;
        let len = (dx * dx + dy * dy).sqrt();
        if len == 0.0 {
            continue;
        }
        let (ux, uy) = (dx / len, dy / len);
        let (nx, ny) = (-uy, ux); // left-hand normal
        let probe = if PROBE < len * 0.25 { PROBE } else { len * 0.25 };

        // Nudge along the segment as well, so the probe never lands exactly on
        // a grid line that some other edge is collinear with.
        let mx = s.a.x as f64 + dx * 0.5 + ux * probe * 0.3141592653589793;
        let my = s.a.y as f64 + dy * 0.5 + uy * probe * 0.3141592653589793;

        let left = in_result(subj, clp, mx + nx * probe, my + ny * probe, ct, fill_rule);
        let right = in_result(subj, clp, mx - nx * probe, my - ny * probe, ct, fill_rule);
        if left == right {
            continue; // interior or exterior to the result on both sides
        }
        if left {
            out.push(*s);
        } else {
            out.push(Seg { a: s.b, b: s.a });
        }
    }
    out
}

fn in_result(
    subj: &Paths64,
    clp: &Paths64,
    x: f64,
    y: f64,
    ct: ClipType,
    fill_rule: FillRule,
) -> bool {
    let s = filled(subj, x, y, fill_rule);
    let c = filled(clp, x, y, fill_rule);
    match ct {
        ClipType::Intersection => s && c,
        ClipType::Union => s || c,
        ClipType::Difference => s && !c,
        ClipType::Xor => s != c,
        ClipType::None => false,
    }
}

/// Applies `fill_rule` at (`x`, `y`) using a ray cast towards +x.
fn filled(paths: &Paths64, x: f64, y: f64, fill_rule: FillRule) -> bool {
    let mut crossings: i32 = 0;
    let mut winding: i32 = 0;
    for path in paths {
        for i in 0..path.len() {
            let p1 = path[i];
            let p2 = path[(i + 1) % path.len()];
            let (y1, y2) = (p1.y as f64, p2.y as f64);
            // Half-open rule: an edge counts when it spans y downward-inclusive.
            if (y1 <= y) == (y2 <= y) {
                continue;
            }
            let t = (y - y1) / (y2 - y1);
            let xx = p1.x as f64 + t * (p2.x - p1.x) as f64;
            if xx > x {
                crossings += 1;
                if y2 > y1 {
                    winding += 1;
                } else {
                    winding -= 1;
                }
            }
        }
    }
    match fill_rule {
        FillRule::EvenOdd => crossings % 2 != 0,
        FillRule::NonZero => winding != 0,
        FillRule::Positive => winding > 0,
        FillRule::Negative => winding < 0,
    }
}

/// Stitches directed boundary segments into closed loops. Where several
/// segments leave a node, the one that turns furthest clockwise is taken, which
/// keeps the traced loops from crossing themselves.
fn stitch(boundary: &[Seg]) -> Vec<Vec<Point64>> {
    let mut outgoing: HashMap<Point64, Vec<usize>> = HashMap::new();
    for (i, s) in boundary.iter().enumerate() {
        outgoing.entry(s.a).or_default().push(i);
    }
    let mut used = vec![false; boundary.len()];
    let mut loops: Vec<Vec<Point64>> = Vec::new();

    for start in 0..boundary.len() {
        if used[start] {
            continue;
        }
        let origin = boundary[start].a;
        let mut pts: Vec<Point64> = vec![origin];
        let mut cur = start;
        loop {
            used[cur] = true;
            let end = boundary[cur].b;
            if end == origin {
                break;
            }
            pts.push(end);
            match next_segment(boundary, &used, &outgoing, cur, end) {
                Some(next) => cur = next,
                None => break, // dead end: close up what we have
            }
        }
        if pts.len() >= 3 {
            loops.push(pts);
        }
    }
    loops
}

fn next_segment(
    boundary: &[Seg],
    used: &[bool],
    outgoing: &HashMap<Point64, Vec<usize>>,
    cur: usize,
    end: Point64,
) -> Option<usize> {
    let incoming = boundary[cur];
    let back = (
        (incoming.a.x - incoming.b.x) as f64,
        (incoming.a.y - incoming.b.y) as f64,
    );
    let back_angle = back.1.atan2(back.0);

    let mut best: Option<(f64, usize)> = None;
    if let Some(cands) = outgoing.get(&end) {
        for &i in cands {
            if used[i] {
                continue;
            }
            let s = boundary[i];
            let angle = ((s.b.y - s.a.y) as f64).atan2((s.b.x - s.a.x) as f64);
            // Clockwise sweep starting from the direction we came in on.
            let mut delta = back_angle - angle;
            while delta <= 0.0 {
                delta += std::f64::consts::TAU;
            }
            if best.map_or(true, |(d, _)| delta < d) {
                best = Some((delta, i));
            }
        }
    }
    if let Some((_, i)) = best {
        return Some(i);
    }

    // Rounding can leave a node marginally off an edge it should have split.
    // Bridge such a hairline gap rather than abandoning the loop.
    let mut nearest: Option<(i128, usize)> = None;
    for (i, s) in boundary.iter().enumerate() {
        if used[i] {
            continue;
        }
        let d = dist_sq(end, s.a);
        if d > 0 && d <= STITCH_TOLERANCE_SQ && nearest.map_or(true, |(bd, _)| d < bd) {
            nearest = Some((d, i));
        }
    }
    nearest.map(|(_, i)| i)
}

/// Removes repeated and collinear vertices and rejects degenerate loops, as
/// Clipper2 does for its solutions (`PreserveCollinear` defaults to off).
fn tidy(mut pts: Vec<Point64>) -> Option<Path64> {
    // Repeated vertices, cyclically.
    let mut cleaned: Vec<Point64> = Vec::with_capacity(pts.len());
    for p in pts.drain(..) {
        if cleaned.last() != Some(&p) {
            cleaned.push(p);
        }
    }
    while cleaned.len() > 1 && cleaned[0] == cleaned[cleaned.len() - 1] {
        cleaned.pop();
    }
    if cleaned.len() < 3 {
        return None;
    }

    // Collinear vertices, cyclically.
    loop {
        let n = cleaned.len();
        if n < 3 {
            return None;
        }
        let mut removed = false;
        let mut i = 0;
        while i < cleaned.len() && cleaned.len() >= 3 {
            let n = cleaned.len();
            let prev = cleaned[(i + n - 1) % n];
            let cur = cleaned[i];
            let next = cleaned[(i + 1) % n];
            if cross_product(prev, cur, next) == 0 {
                cleaned.remove(i);
                removed = true;
            } else {
                i += 1;
            }
        }
        if !removed {
            break;
        }
    }
    if cleaned.len() < 3 || area(&cleaned) == 0.0 {
        return None;
    }
    Some(cleaned)
}

