//! Regression tests for the boolean operations. Every expectation here was
//! derived by hand from the geometry, independently of the implementation.

use clipper2_test5::clipper2::clipper::{difference, intersect, union, xor};
use clipper2_test5::clipper2::core::{area, FillRule, Path64, Paths64, Point64};

fn p(x: i64, y: i64) -> Point64 {
    Point64::new(x, y)
}

fn rect(x1: i64, y1: i64, x2: i64, y2: i64) -> Path64 {
    vec![p(x1, y1), p(x2, y1), p(x2, y2), p(x1, y2)]
}

fn total_area(paths: &Paths64) -> f64 {
    paths.iter().map(|p| area(p)).sum()
}

/// The configuration used by test5.cpp.
#[test]
fn overlapping_squares() {
    let s: Paths64 = vec![rect(0, 0, 100, 100)];
    let c: Paths64 = vec![rect(50, 50, 150, 150)];

    let i = intersect(&s, &c, FillRule::EvenOdd);
    assert_eq!(i.len(), 1);
    assert_eq!(i[0].len(), 4);
    assert_eq!(total_area(&i), 2500.0);

    let u = union(&s, &c, FillRule::EvenOdd);
    assert_eq!(u.len(), 1);
    assert_eq!(u[0].len(), 8);
    assert_eq!(total_area(&u), 17500.0);

    let d = difference(&s, &c, FillRule::EvenOdd);
    assert_eq!(d.len(), 1);
    assert_eq!(d[0].len(), 6);
    assert_eq!(total_area(&d), 7500.0);

    let x = xor(&s, &c, FillRule::EvenOdd);
    assert_eq!(x.len(), 2);
    assert_eq!(total_area(&x), 15000.0);
}

#[test]
fn disjoint_squares() {
    let s: Paths64 = vec![rect(0, 0, 10, 10)];
    let c: Paths64 = vec![rect(20, 20, 30, 30)];
    assert!(intersect(&s, &c, FillRule::EvenOdd).is_empty());
    assert_eq!(union(&s, &c, FillRule::EvenOdd).len(), 2);
    assert_eq!(difference(&s, &c, FillRule::EvenOdd).len(), 1);
    assert_eq!(xor(&s, &c, FillRule::EvenOdd).len(), 2);
}

/// A clip fully inside the subject leaves a hole, which must come back with a
/// negative orientation.
#[test]
fn nested_clip_produces_a_hole() {
    let s: Paths64 = vec![rect(0, 0, 100, 100)];
    let c: Paths64 = vec![rect(25, 25, 75, 75)];

    let d = difference(&s, &c, FillRule::EvenOdd);
    assert_eq!(d.len(), 2);
    assert_eq!(area(&d[0]), 10000.0);
    assert_eq!(area(&d[1]), -2500.0);
    assert_eq!(total_area(&d), 7500.0);

    let u = union(&s, &c, FillRule::EvenOdd);
    assert_eq!(u.len(), 1);
    assert_eq!(total_area(&u), 10000.0);
}

#[test]
fn shared_edge_and_identical_inputs() {
    let left: Paths64 = vec![rect(0, 0, 50, 50)];
    let right: Paths64 = vec![rect(50, 0, 100, 50)];
    // Touching along an edge: no area in common.
    assert!(intersect(&left, &right, FillRule::EvenOdd).is_empty());
    let u = union(&left, &right, FillRule::EvenOdd);
    assert_eq!(u.len(), 1);
    assert_eq!(u[0].len(), 4, "the shared edge must vanish");
    assert_eq!(total_area(&u), 5000.0);

    // Identical inputs.
    assert_eq!(total_area(&intersect(&left, &left, FillRule::EvenOdd)), 2500.0);
    assert!(difference(&left, &left, FillRule::EvenOdd).is_empty());
    assert!(xor(&left, &left, FillRule::EvenOdd).is_empty());
}

/// Two overlapping subject rectangles: EvenOdd leaves their overlap unfilled,
/// NonZero does not.
#[test]
fn fill_rules_differ_on_overlapping_subjects() {
    let cross: Paths64 = vec![rect(30, 0, 70, 100), rect(0, 30, 100, 70)];
    let centre: Paths64 = vec![rect(25, 25, 75, 75)];

    let eo = intersect(&cross, &centre, FillRule::EvenOdd);
    assert_eq!(eo.len(), 4, "the unfilled centre splits the result in four");
    assert_eq!(total_area(&eo), 800.0);

    let nz = intersect(&cross, &centre, FillRule::NonZero);
    assert_eq!(nz.len(), 1);
    assert_eq!(total_area(&nz), 2400.0);
}

/// Intersections that are not on the integer grid get rounded, as in Clipper2.
#[test]
fn triangles_with_computed_intersections() {
    let s: Paths64 = vec![vec![p(0, 0), p(100, 0), p(0, 100)]];
    let c: Paths64 = vec![vec![p(0, 30), p(100, 30), p(100, 130)]];

    let i = intersect(&s, &c, FillRule::EvenOdd);
    assert_eq!(i.len(), 1);
    assert_eq!(total_area(&i), 1225.0);

    assert_eq!(total_area(&union(&s, &c, FillRule::EvenOdd)), 8775.0);
    assert_eq!(total_area(&difference(&s, &c, FillRule::EvenOdd)), 3775.0);
    assert_eq!(total_area(&xor(&s, &c, FillRule::EvenOdd)), 7550.0);
}

#[test]
fn self_intersecting_subject() {
    let bowtie: Paths64 = vec![vec![p(0, 0), p(100, 100), p(100, 0), p(0, 100)]];
    let band: Paths64 = vec![rect(-10, 40, 110, 60)];

    let i = intersect(&bowtie, &band, FillRule::EvenOdd);
    assert_eq!(i.len(), 2, "one lobe of the bowtie each");
    assert_eq!(total_area(&i), 1800.0);
    assert_eq!(total_area(&union(&bowtie, &band, FillRule::EvenOdd)), 5600.0);
    assert_eq!(total_area(&difference(&bowtie, &band, FillRule::EvenOdd)), 3200.0);
    assert_eq!(total_area(&xor(&bowtie, &band, FillRule::EvenOdd)), 3800.0);
}

#[test]
fn empty_operands() {
    let s: Paths64 = vec![rect(0, 0, 10, 10)];
    let empty = Paths64::new();

    assert!(intersect(&s, &empty, FillRule::EvenOdd).is_empty());
    assert_eq!(total_area(&union(&s, &empty, FillRule::EvenOdd)), 100.0);
    assert_eq!(total_area(&difference(&s, &empty, FillRule::EvenOdd)), 100.0);
    assert_eq!(total_area(&xor(&s, &empty, FillRule::EvenOdd)), 100.0);

    assert!(intersect(&empty, &s, FillRule::EvenOdd).is_empty());
    assert!(difference(&empty, &s, FillRule::EvenOdd).is_empty());
    assert_eq!(total_area(&union(&empty, &s, FillRule::EvenOdd)), 100.0);
    assert!(union(&empty, &empty, FillRule::EvenOdd).is_empty());
}

/// Degenerate input paths carry no area and are ignored.
#[test]
fn degenerate_inputs_are_dropped() {
    let s: Paths64 = vec![
        vec![p(0, 0), p(10, 0)],                 // two points
        vec![p(0, 0), p(0, 0), p(0, 0)],         // all identical
        rect(0, 0, 10, 10),
    ];
    let c: Paths64 = vec![rect(5, 5, 15, 15)];
    let i = intersect(&s, &c, FillRule::EvenOdd);
    assert_eq!(i.len(), 1);
    assert_eq!(total_area(&i), 25.0);
}

/// Coordinates far from the origin must not overflow the exact predicates.
#[test]
fn large_coordinates() {
    let m = 1_000_000_000i64;
    let s: Paths64 = vec![rect(-m, -m, m, m)];
    let c: Paths64 = vec![rect(0, 0, 2 * m, 2 * m)];
    let i = intersect(&s, &c, FillRule::EvenOdd);
    assert_eq!(i.len(), 1);
    assert_eq!(total_area(&i), (m as f64) * (m as f64));
}

