// Rust port of tests/test5.cpp from the Clipper2 test-suite.
//
// Exercises five API entry points: the Path64/Paths64 containers plus the four
// boolean clipping operations (Intersect, Union, Difference, Xor).

#[path = "src/clipper2/mod.rs"]
mod clipper2;

use clipper2::clipper::{difference, intersect, union, xor};
use clipper2::core::{FillRule, Path64, Paths64, Point64};

fn main() {
    // The C++ program ignores argc/argv; consume them the same way so the
    // binary accepts an identical command line.
    let _args: Vec<String> = std::env::args().collect();

    // 5个API：布尔操作 - 交集
    let subject: Path64 = vec![
        Point64::new(0, 0),
        Point64::new(100, 0),
        Point64::new(100, 100),
        Point64::new(0, 100),
    ];
    let clip: Path64 = vec![
        Point64::new(50, 50),
        Point64::new(150, 50),
        Point64::new(150, 150),
        Point64::new(50, 150),
    ];

    let subjects: Paths64 = vec![subject];
    let clips: Paths64 = vec![clip];

    // 调用5个API：交集操作
    let intersection = intersect(&subjects, &clips, FillRule::EvenOdd);
    let _union_result = union(&subjects, &clips, FillRule::EvenOdd);
    let _difference = difference(&subjects, &clips, FillRule::EvenOdd);
    let _xor_result = xor(&subjects, &clips, FillRule::EvenOdd);

    println!("{}", intersection.len());
}
